def prepare():
    rows=read(OUT/'candidates.json');pois={p['id']:p for p in csv.DictReader((ROOT/'data/sources/settlements/nrct-poi-20250515.csv').open(encoding='utf-8-sig'))}
    chosen={int(t.split(':')[0]):t.split(':')[1] for t in POI_IDS.split()}
    for i,r in enumerate(rows):
        if i in REPLACE:r['name'],r['province'],r['role']=REPLACE[i]
        r['index']=i;r.pop('poi_candidates')
        if i in chosen:
            p=pois[chosen[i]];r.update(lonlat=[float(p['経度']),float(p['緯度'])],poi_id=p['id'],location_note=p['名称']+' / '+p['住所']+'。現代地名データの地域代表点。近世改修前の曲輪範囲や1582年の岸線は未確定。')
        elif i in MANUAL:
            x,y,note=MANUAL[i];r.update(lonlat=[x,y],poi_id=None,location_note=note+'。所在地説明に基づく手動の地域代表点で、測量・原図補正は未実施。')
        else:raise ValueError((i,r['name']))
    write(OUT/'reviewed_locations.json',rows)
    print('Locations prepared:',len(rows))
if __name__=='__main__':prepare()
